export class ImagingClient {
  readonly #device: Device

  constructor(device: Device) {
    this.#device = device
  }

  /**
   * @param videoSourceToken - The `VideoSourceToken` of every request
   * @returns The operations that take a `VideoSourceToken`, without it in the request
   */
  forVideoSource(videoSourceToken: string): ImagingVideoSourceClient {
    return new ImagingVideoSourceClient(this.#device, videoSourceToken)
  }

  /**
   * Returns the capabilities of the imaging service. The result is returned in a typed answer.
   *
   * @param request - The `GetServiceCapabilities` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetServiceCapabilitiesResponse`
   */
  getServiceCapabilities(
    request?: GetServiceCapabilitiesRequest,
    options?: CallOptions
  ): Promise<GetServiceCapabilitiesResponse> {
    return this.#device.call(GetServiceCapabilities, request, options)
  }

  /**
   * Get the ImagingConfiguration for the requested VideoSource.
   *
   * @param request - The `GetImagingSettings` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetImagingSettingsResponse`
   */
  getImagingSettings(request: GetImagingSettingsRequest, options?: CallOptions): Promise<GetImagingSettingsResponse> {
    return this.#device.call(GetImagingSettings, request, options)
  }

  /**
   * Set the ImagingConfiguration for the requested VideoSource.
   *
   * @param request - The `SetImagingSettings` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetImagingSettingsResponse`
   */
  setImagingSettings(request: SetImagingSettingsRequest, options?: CallOptions): Promise<SetImagingSettingsResponse> {
    return this.#device.call(SetImagingSettings, request, options)
  }

  /**
   * This operation gets the valid ranges for the imaging parameters that have device specific ranges.
   * This command is mandatory for all device implementing the imaging service. The command returns all
   * supported parameters and their ranges such that these can be applied to the SetImagingSettings
   * command. For read-only parameters which cannot be modified via the SetImagingSettings command only a
   * single option or identical Min and Max values is provided.
   *
   * @param request - The `GetOptions` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetOptionsResponse`
   */
  getOptions(request: GetOptionsRequest, options?: CallOptions): Promise<GetOptionsResponse> {
    return this.#device.call(GetOptions, request, options)
  }

  /**
   * The Move command moves the focus lens in an absolute, a relative or in a continuous manner from its
   * current position. The speed argument is optional for absolute and relative control, but required for
   * continuous. If no speed argument is used, the default speed is used. Focus adjustments through this
   * operation will turn off the autofocus. A device with support for remote focus control should support
   * absolute, relative or continuous control through the Move operation. The supported MoveOpions are
   * signalled via the GetMoveOptions command. At least one focus control capability is required for this
   * operation to be functional. The move operation contains the following commands: Absolute - Requires
   * position parameter and optionally takes a speed argument. A unitless type is used by default for
   * focus positioning and speed. Optionally, if supported, the position may be requested in m-1 units.
   * Relative - Requires distance parameter and optionally takes a speed argument. Negative distance
   * means negative direction. Continuous - Requires a speed argument. Negative speed argument means
   * negative direction.
   *
   * @param request - The `Move` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `MoveResponse`
   */
  move(request: MoveRequest, options?: CallOptions): Promise<MoveResponse> {
    return this.#device.call(Move, request, options)
  }

  /**
   * Imaging move operation options supported for the Video source.
   *
   * @param request - The `GetMoveOptions` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetMoveOptionsResponse`
   */
  getMoveOptions(request: GetMoveOptionsRequest, options?: CallOptions): Promise<GetMoveOptionsResponse> {
    return this.#device.call(GetMoveOptions, request, options)
  }

  /**
   * The Stop command stops all ongoing focus movements of the lense. A device with support for remote
   * focus control as signalled via the GetMoveOptions supports this command. The operation will not
   * affect ongoing autofocus operation.
   *
   * @param request - The `Stop` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `StopResponse`
   */
  stop(request: StopRequest, options?: CallOptions): Promise<StopResponse> {
    return this.#device.call(Stop, request, options)
  }

  /**
   * Via this command the current status of the Move operation can be requested. Supported for this
   * command is available if the support for the Move operation is signalled via GetMoveOptions.
   *
   * @param request - The `GetStatus` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetStatusResponse`
   */
  getStatus(request: GetStatusRequest, options?: CallOptions): Promise<GetStatusResponse> {
    return this.#device.call(GetStatus, request, options)
  }

  /**
   * Via this command the list of available Imaging Presets can be requested.
   *
   * @param request - The `GetPresets` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetPresetsResponse`
   */
  getPresets(request: GetPresetsRequest, options?: CallOptions): Promise<GetPresetsResponse> {
    return this.#device.call(GetPresets, request, options)
  }

  /**
   * Via this command the last Imaging Preset applied can be requested. If the camera configuration does
   * not match any of the existing Imaging Presets, the output of GetCurrentPreset shall be Empty.
   * GetCurrentPreset shall return 0 if Imaging Presets are not supported by the Video Source.
   *
   * @param request - The `GetCurrentPreset` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetCurrentPresetResponse`
   */
  getCurrentPreset(request: GetCurrentPresetRequest, options?: CallOptions): Promise<GetCurrentPresetResponse> {
    return this.#device.call(GetCurrentPreset, request, options)
  }

  /**
   * The SetCurrentPreset command shall request a given Imaging Preset to be applied to the specified
   * Video Source. SetCurrentPreset shall only be available for Video Sources with Imaging Presets
   * Capability. Imaging Presets are defined by the Manufacturer, and offered as a tool to simplify
   * Imaging Settings adjustments for specific scene content. When the new Imaging Preset is applied by
   * SetCurrentPreset, the Device shall adjust the Video Source settings to match those defined by the
   * specified Imaging Preset.
   *
   * @param request - The `SetCurrentPreset` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetCurrentPresetResponse`
   */
  setCurrentPreset(request: SetCurrentPresetRequest, options?: CallOptions): Promise<SetCurrentPresetResponse> {
    return this.#device.call(SetCurrentPreset, request, options)
  }
}

export class ImagingVideoSourceClient {
  readonly #device: Device
  readonly #videoSourceToken: string

  constructor(device: Device, videoSourceToken: string) {
    this.#device = device
    this.#videoSourceToken = videoSourceToken
  }

  /**
   * Get the ImagingConfiguration for the requested VideoSource.
   *
   * @param request - The `GetImagingSettings` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetImagingSettingsResponse`
   */
  getImagingSettings(
    request?: Omit<GetImagingSettingsRequest, 'videoSourceToken'>,
    options?: CallOptions
  ): Promise<GetImagingSettingsResponse> {
    return this.#device.call(GetImagingSettings, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * Set the ImagingConfiguration for the requested VideoSource.
   *
   * @param request - The `SetImagingSettings` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetImagingSettingsResponse`
   */
  setImagingSettings(
    request: Omit<SetImagingSettingsRequest, 'videoSourceToken'>,
    options?: CallOptions
  ): Promise<SetImagingSettingsResponse> {
    return this.#device.call(SetImagingSettings, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * This operation gets the valid ranges for the imaging parameters that have device specific ranges.
   * This command is mandatory for all device implementing the imaging service. The command returns all
   * supported parameters and their ranges such that these can be applied to the SetImagingSettings
   * command. For read-only parameters which cannot be modified via the SetImagingSettings command only a
   * single option or identical Min and Max values is provided.
   *
   * @param request - The `GetOptions` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetOptionsResponse`
   */
  getOptions(
    request?: Omit<GetOptionsRequest, 'videoSourceToken'>,
    options?: CallOptions
  ): Promise<GetOptionsResponse> {
    return this.#device.call(GetOptions, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * The Move command moves the focus lens in an absolute, a relative or in a continuous manner from its
   * current position. The speed argument is optional for absolute and relative control, but required for
   * continuous. If no speed argument is used, the default speed is used. Focus adjustments through this
   * operation will turn off the autofocus. A device with support for remote focus control should support
   * absolute, relative or continuous control through the Move operation. The supported MoveOpions are
   * signalled via the GetMoveOptions command. At least one focus control capability is required for this
   * operation to be functional. The move operation contains the following commands: Absolute - Requires
   * position parameter and optionally takes a speed argument. A unitless type is used by default for
   * focus positioning and speed. Optionally, if supported, the position may be requested in m-1 units.
   * Relative - Requires distance parameter and optionally takes a speed argument. Negative distance
   * means negative direction. Continuous - Requires a speed argument. Negative speed argument means
   * negative direction.
   *
   * @param request - The `Move` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `MoveResponse`
   */
  move(request: Omit<MoveRequest, 'videoSourceToken'>, options?: CallOptions): Promise<MoveResponse> {
    return this.#device.call(Move, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * Imaging move operation options supported for the Video source.
   *
   * @param request - The `GetMoveOptions` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetMoveOptionsResponse`
   */
  getMoveOptions(
    request?: Omit<GetMoveOptionsRequest, 'videoSourceToken'>,
    options?: CallOptions
  ): Promise<GetMoveOptionsResponse> {
    return this.#device.call(GetMoveOptions, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * The Stop command stops all ongoing focus movements of the lense. A device with support for remote
   * focus control as signalled via the GetMoveOptions supports this command. The operation will not
   * affect ongoing autofocus operation.
   *
   * @param request - The `Stop` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `StopResponse`
   */
  stop(request?: Omit<StopRequest, 'videoSourceToken'>, options?: CallOptions): Promise<StopResponse> {
    return this.#device.call(Stop, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * Via this command the current status of the Move operation can be requested. Supported for this
   * command is available if the support for the Move operation is signalled via GetMoveOptions.
   *
   * @param request - The `GetStatus` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetStatusResponse`
   */
  getStatus(request?: Omit<GetStatusRequest, 'videoSourceToken'>, options?: CallOptions): Promise<GetStatusResponse> {
    return this.#device.call(GetStatus, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * Via this command the list of available Imaging Presets can be requested.
   *
   * @param request - The `GetPresets` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetPresetsResponse`
   */
  getPresets(
    request?: Omit<GetPresetsRequest, 'videoSourceToken'>,
    options?: CallOptions
  ): Promise<GetPresetsResponse> {
    return this.#device.call(GetPresets, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * Via this command the last Imaging Preset applied can be requested. If the camera configuration does
   * not match any of the existing Imaging Presets, the output of GetCurrentPreset shall be Empty.
   * GetCurrentPreset shall return 0 if Imaging Presets are not supported by the Video Source.
   *
   * @param request - The `GetCurrentPreset` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetCurrentPresetResponse`
   */
  getCurrentPreset(
    request?: Omit<GetCurrentPresetRequest, 'videoSourceToken'>,
    options?: CallOptions
  ): Promise<GetCurrentPresetResponse> {
    return this.#device.call(GetCurrentPreset, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }

  /**
   * The SetCurrentPreset command shall request a given Imaging Preset to be applied to the specified
   * Video Source. SetCurrentPreset shall only be available for Video Sources with Imaging Presets
   * Capability. Imaging Presets are defined by the Manufacturer, and offered as a tool to simplify
   * Imaging Settings adjustments for specific scene content. When the new Imaging Preset is applied by
   * SetCurrentPreset, the Device shall adjust the Video Source settings to match those defined by the
   * specified Imaging Preset.
   *
   * @param request - The `SetCurrentPreset` request without `videoSourceToken`
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `SetCurrentPresetResponse`
   */
  setCurrentPreset(
    request: Omit<SetCurrentPresetRequest, 'videoSourceToken'>,
    options?: CallOptions
  ): Promise<SetCurrentPresetResponse> {
    return this.#device.call(SetCurrentPreset, { ...request, videoSourceToken: this.#videoSourceToken }, options)
  }
}
